"""Intrinsic-backed compatibility surface for CPython's `_json`."""

from _intrinsics import require_intrinsic as _require_intrinsic

_MOLT_JSON_DUMPS_EX = _require_intrinsic("molt_json_dumps_ex")
_MOLT_JSON_DEFAULT_SEPARATORS = _require_intrinsic("molt_json_default_separators")
# BEGIN PUBLIC OBJECT molt_json_encode_basestring_obj
# Generated by tools/gen_intrinsics.py from public_objects.toml.
encode_basestring = _require_intrinsic('molt_json_encode_basestring_obj')
# END PUBLIC OBJECT molt_json_encode_basestring_obj
# BEGIN PUBLIC OBJECT molt_json_encode_basestring_ascii_obj
# Generated by tools/gen_intrinsics.py from public_objects.toml.
encode_basestring_ascii = _require_intrinsic('molt_json_encode_basestring_ascii_obj')
# END PUBLIC OBJECT molt_json_encode_basestring_ascii_obj
# BEGIN PUBLIC OBJECT molt_json_scanstring_obj
# Generated by tools/gen_intrinsics.py from public_objects.toml.
scanstring = _require_intrinsic('molt_json_scanstring_obj')
# END PUBLIC OBJECT molt_json_scanstring_obj


class Encoder:
    def __init__(
        self,
        markers,
        default,
        encoder,
        indent,
        key_separator,
        item_separator,
        sort_keys,
        skipkeys,
        allow_nan,
    ) -> None:
        self.markers = markers
        self.default = default
        self.encoder = encoder
        self.indent = indent
        self.key_separator = key_separator
        self.item_separator = item_separator
        self.sort_keys = sort_keys
        self.skipkeys = skipkeys
        self.allow_nan = allow_nan

    def __call__(
        self,
        obj,
        _current_indent_level,
        _dumps_ex=_MOLT_JSON_DUMPS_EX,
        _default_separators=_MOLT_JSON_DEFAULT_SEPARATORS,
    ):
        separators = (self.item_separator, self.key_separator)
        if separators == (None, None):
            separators = _default_separators(self.indent)
        text = _dumps_ex(
            obj,
            self.skipkeys,
            self.encoder is encode_basestring_ascii,
            self.markers is not None,
            self.allow_nan,
            self.sort_keys,
            self.indent,
            separators[0],
            separators[1],
            self.default,
        )
        return (text,)


class Scanner:
    def __init__(self, context) -> None:
        self.context = context

    def __call__(self, string, idx):
        return self.context.raw_decode(string, idx)


del _MOLT_JSON_DUMPS_EX
del _MOLT_JSON_DEFAULT_SEPARATORS
globals().pop("_require_intrinsic", None)


make_encoder = Encoder
make_scanner = Scanner
del Encoder, Scanner
